const mobile=document.querySelector('.mobile-toggle'),nav=document.querySelector('#primary-nav'),expertise=document.querySelector('.expertise-toggle'),menu=document.querySelector('#expertise-menu');mobile.addEventListener('click',()=>{const open=mobile.getAttribute('aria-expanded')!=='true';mobile.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});expertise.addEventListener('click',()=>{const open=expertise.getAttribute('aria-expanded')!=='true';expertise.setAttribute('aria-expanded',String(open));menu.hidden=!open});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;expertise.setAttribute('aria-expanded','false');nav.classList.remove('open');mobile.setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!e.target.closest('.nav-dropdown')){menu.hidden=true;expertise.setAttribute('aria-expanded','false')}});const audiences={government:['PUBLIC POLICY INTO PUBLIC VALUE','How does reform become something institutions can deliver?','Clarify institutional responsibilities, understand barriers to formal participation and sequence practical reforms around capacity, safeguards and development priorities.'],dfi:['DEVELOPMENT LOGIC INTO IMPLEMENTABLE INTERVENTIONS','What makes a mineral-sector intervention credible?','Connect the development rationale to an institutional diagnostic, realistic implementation arrangements, safeguard considerations and measurable results. Identify evidence gaps before commitments are made.'],programme:['PROGRAMME AMBITION INTO COORDINATED ACTION','How will the programme turn intent into accountable delivery?','Define the theory of change, stakeholder roles, workstreams and indicators. Build participation, learning and institutional ownership into the programme from inception.']};document.querySelectorAll('[data-audience]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-audience]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));const d=audiences[b.dataset.audience];['kicker','title','text'].forEach((x,i)=>document.querySelector('#audience-'+x).textContent=d[i]);document.querySelector('#audience-panel').setAttribute('aria-labelledby',b.id)}));const form=document.querySelector('#enquiry');if(form)form.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(form);location.href='mailto:partnerships@beldium.com?subject='+encodeURIComponent('Institutional enquiry: '+f.get('focus'))+'&body='+encodeURIComponent(`Name: ${f.get('name')}\nEmail: ${f.get('email')}\nInstitution: ${f.get('org')}\nFocus: ${f.get('focus')}\n\n${f.get('message')}`);document.querySelector('#status').textContent='Please review and send the enquiry in your email application. If it did not open, email partnerships@beldium.com directly.'});const legacy={contact:'/contact/',expertise:'/expertise/asm-formalisation/',approach:'/approach/',about:'/about/',formalisation:'/expertise/asm-formalisation/'};if(location.pathname==='/'&&legacy[location.hash.slice(1)])location.replace(legacy[location.hash.slice(1)]);const currentPath=location.pathname;document.querySelectorAll('#primary-nav a').forEach(a=>{if(new URL(a.href).pathname===currentPath)a.setAttribute('aria-current','page')});const tabs=[...document.querySelectorAll('[data-audience]')];tabs.forEach((b,i)=>b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();tabs[n].click()}}));
